import React, { useMemo, useRef, useState } from 'react';
import './App.css';

// The arrow keys move through the stars the way they move through any radio group.
const ARROW_STEPS: Record<string, number> = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };

type StarRatingProps = {
  max?: number;
  rating: number;
  onChange: (value: number) => void;
};

function StarRating({ max = 5, rating, onChange }: StarRatingProps) {
  const stars = useMemo(
    () => Array.from({ length: max }, (_, i) => i + 1),
    [max]
  );
  const starRefs = useRef<Array<HTMLButtonElement | null>>([]);
  // A radio group is one Tab stop: the checked star, or the first star before anything is rated.
  const tabStop = rating > 0 ? rating : 1;

  const handleRate = (value: number) => {
    if (value < 1 || value > max) return;
    onChange(value);
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>, star: number) => {
    const step = ARROW_STEPS[event.key];
    if (!step) return;
    // The arrows would otherwise scroll the page.
    event.preventDefault();
    const next = ((star - 1 + step + max) % max) + 1;
    handleRate(next);
    starRefs.current[next - 1]?.focus();
  };

  return (
    <div className="stars" role="radiogroup" aria-label="Star rating">
      {stars.map((star) => (
        <button
          key={star}
          ref={(element) => {
            starRefs.current[star - 1] = element;
          }}
          type="button"
          role="radio"
          className={"star" + (star <= rating ? " filled" : "")}
          onClick={() => handleRate(star)}
          onKeyDown={(event) => handleKeyDown(event, star)}
          aria-label={`${star} out of ${max}`}
          aria-checked={star === rating}
          tabIndex={star === tabStop ? 0 : -1}
        >
          ★
        </button>
      ))}
    </div>
  );
}

export default function App() {
  const [currentRating, setCurrentRating] = useState(0);

  return (
    <main className="main">
      <section className="section">
        <h1>Star Rating Widget (Solution)</h1>

        <div className="panel">
          <StarRating rating={currentRating} onChange={setCurrentRating} />
          <p className="hint">Current rating: {currentRating} / 5</p>
        </div>
      </section>
    </main>
  );
}
